style.css:
@-moz-document url-prefix("https://archiveofourown.org/skins") {
/* STYLUS: Camp Jupiter / Riordan‑Verse Full Theme */

/* Custom Roman-style font */
@font-face {
  font-family: 'ImperialRoman';
  src: url('https://cdn.jsdelivr.net/gh/google/fonts@main/ofl/cinzel/Cinzel-Regular.ttf');
}

body {
  font-family: 'ImperialRoman', serif;
  background: url('https://i.imgur.com/2u7FQ0E.jpg') repeat; /* stone texture */
  color: #f0e6ff;
}

/* Purple + gold palette */
a, .heading, h1, h2, h3 {
  color: #d4af37; /* gold */
}

.userstuff {
  background: rgba(40, 0, 60, 0.7);
  padding: 1.5em;
  border: 3px solid #d4af37;
  border-radius: 8px;
}

/* Chapter dividers */
hr {
  border: 0;
  height: 4px;
  background: linear-gradient(to right, #d4af37, #6a0dad, #d4af37);
  margin: 2em 0;
}

/* Optional: subtle glow on headers */
h1, h2, h3 {
  text-shadow: 0 0 6px #6a0dad;
}
}
